-- Additive write-once protection for the 0050 ordinary DELETE origin and post-COMMIT seal.
-- This does not classify origin-less tombstones or authorize/schedule physical purge.  The
-- migration must run with all pre-0051 writers stopped; the trigger is create-only on replay.

CREATE TRIGGER trg_sessions_ordinary_delete_grace_bu BEFORE UPDATE ON sessions FOR EACH ROW BEGIN IF OLD.ordinary_delete_origin_sha256 IS NULL AND NEW.ordinary_delete_origin_sha256 IS NOT NULL AND (OLD.deleted_at_ms IS NOT NULL OR NEW.deleted_at_ms IS NULL OR NEW.ordinary_delete_seal_observed_db_ms IS NOT NULL OR NEW.ordinary_delete_grace_floor_db_ms IS NOT NULL OR NEW.ordinary_delete_seal_sha256 IS NOT NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary DELETE origin must accompany first tombstone'; END IF; IF OLD.ordinary_delete_origin_sha256 IS NOT NULL AND (NOT (OLD.ordinary_delete_origin_sha256 <=> NEW.ordinary_delete_origin_sha256) OR NOT (OLD.ordinary_delete_origin_observed_db_ms <=> NEW.ordinary_delete_origin_observed_db_ms) OR NOT (BINARY OLD.tenant_id <=> BINARY NEW.tenant_id) OR NOT (BINARY OLD.user_id <=> BINARY NEW.user_id) OR NOT (BINARY OLD.session_id <=> BINARY NEW.session_id) OR NOT (OLD.deleted_at_ms <=> NEW.deleted_at_ms) OR NOT (OLD.deletion_generation <=> NEW.deletion_generation) OR NOT (OLD.last_seq <=> NEW.last_seq)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary DELETE origin is immutable'; END IF; IF OLD.ordinary_delete_seal_sha256 IS NULL AND NEW.ordinary_delete_seal_sha256 IS NOT NULL AND OLD.ordinary_delete_origin_sha256 IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary DELETE seal requires prior origin row version'; END IF; IF OLD.ordinary_delete_seal_sha256 IS NOT NULL AND (NOT (OLD.ordinary_delete_seal_observed_db_ms <=> NEW.ordinary_delete_seal_observed_db_ms) OR NOT (OLD.ordinary_delete_grace_floor_db_ms <=> NEW.ordinary_delete_grace_floor_db_ms) OR NOT (OLD.ordinary_delete_seal_sha256 <=> NEW.ordinary_delete_seal_sha256)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary DELETE seal is immutable'; END IF; END;
